/**
 * "Write a plugin from a description" (§6.5.4, §9): the pure state machine
 * and the parsing helpers behind the plugin writer sheet.
 *
 *   idle → generating → result | failed → enabled | discarded
 *
 * The plugin is generated by `ai.generate-plugin`, which tests it in the
 * plugin sandbox and installs it TURNED OFF. Nothing here ever enables a
 * plugin by itself: turning it on is a separate, previewed admin action.
 */

/** `ai.generate-plugin` output (packages/ai/src/plugin-gen.ts). */
export interface GeneratePluginOutput {
  id: string;
  code: string;
  tests: string;
  tested: boolean;
  testResult?: { ok: boolean; passed?: number; failed?: number; output?: string };
  installed: boolean;
  enabled: false;
  problems: string[];
  note: string;
  /** Not sent yet (backend gap): plain name / summary / declared permissions. */
  name?: string;
  summary?: string;
  permissions?: string[];
}

export type WriterState =
  | { phase: 'idle'; description: string }
  | { phase: 'generating'; description: string; startedAt: number; runId: number }
  | { phase: 'result'; description: string; output: GeneratePluginOutput }
  | { phase: 'failed'; description: string; error: string; output?: GeneratePluginOutput }
  | { phase: 'enabled'; description: string; output: GeneratePluginOutput }
  | { phase: 'discarded'; description: string; output: GeneratePluginOutput };

export type WriterEvent =
  | { type: 'edit'; description: string }
  | { type: 'generate'; now: number }
  | { type: 'success'; runId: number; output: GeneratePluginOutput }
  | { type: 'error'; runId: number; error: string }
  | { type: 'cancel' }
  | { type: 'enabled' }
  | { type: 'enable-undone' }
  | { type: 'discarded' }
  | { type: 'discard-undone' }
  | { type: 'retry' }
  | { type: 'reset' };

export const MIN_DESCRIPTION = 10;
export const MAX_DESCRIPTION = 2000;

export const initialState = (description = ''): WriterState => ({ phase: 'idle', description });

/** Can the description be sent? (same bounds as the action input) */
export function canGenerate(description: string): boolean {
  const d = description.trim();
  return d.length >= MIN_DESCRIPTION && d.length <= MAX_DESCRIPTION;
}

/** The output produced a plugin worth reviewing (code exists and nothing blocked it). */
export function hasPlugin(o: GeneratePluginOutput): boolean {
  return !!o.code.trim() && o.problems.length === 0;
}

/** Tests ran and all passed. */
export function testsPassed(o: GeneratePluginOutput): boolean {
  return o.tested && !!o.testResult?.ok;
}

export type EnableBlock = 'tests-failed' | 'not-tested' | 'not-installed' | null;

/** Why Enable is not possible (null = it may be turned on, after a preview). */
export function enableBlock(o: GeneratePluginOutput): EnableBlock {
  if (o.tested && !o.testResult?.ok) return 'tests-failed';
  if (!o.tested) return 'not-tested';
  if (!o.installed) return 'not-installed';
  return null;
}

let runSeq = 0;

export function reduce(s: WriterState, e: WriterEvent): WriterState {
  switch (e.type) {
    case 'edit':
      return s.phase === 'idle' || s.phase === 'failed'
        ? { phase: 'idle', description: e.description }
        : s;
    case 'generate':
      if ((s.phase !== 'idle' && s.phase !== 'failed') || !canGenerate(s.description)) return s;
      return {
        phase: 'generating',
        description: s.description.trim(),
        startedAt: e.now,
        runId: ++runSeq,
      };
    case 'success':
      if (s.phase !== 'generating' || s.runId !== e.runId) return s;
      if (!hasPlugin(e.output))
        return {
          phase: 'failed',
          description: s.description,
          error: e.output.note,
          output: e.output,
        };
      return { phase: 'result', description: s.description, output: e.output };
    case 'error':
      if (s.phase !== 'generating' || s.runId !== e.runId) return s;
      return { phase: 'failed', description: s.description, error: e.error };
    case 'cancel':
      return s.phase === 'generating' ? { phase: 'idle', description: s.description } : s;
    case 'enabled':
      return s.phase === 'result' && enableBlock(s.output) === null
        ? { phase: 'enabled', description: s.description, output: s.output }
        : s;
    case 'enable-undone':
      return s.phase === 'enabled'
        ? { phase: 'result', description: s.description, output: s.output }
        : s;
    case 'discarded':
      return s.phase === 'result'
        ? { phase: 'discarded', description: s.description, output: s.output }
        : s;
    case 'discard-undone':
      return s.phase === 'discarded'
        ? { phase: 'result', description: s.description, output: s.output }
        : s;
    case 'retry':
      return s.phase === 'generating' ? s : { phase: 'idle', description: s.description };
    case 'reset':
      return s.phase === 'generating' ? s : initialState();
  }
}

/** Is a run id still the one the sheet is waiting for? (late answers after Cancel are ignored) */
export function isCurrentRun(s: WriterState, runId: number): boolean {
  return s.phase === 'generating' && s.runId === runId;
}

// ───────── reading the generated code ─────────

const str = (src: string, key: string): string | undefined => {
  const m = src.match(new RegExp(`\\b${key}\\s*:\\s*(['"\`])((?:\\\\.|(?!\\1).)*)\\1`));
  return m?.[2]?.replace(/\\(['"`\\])/g, '$1');
};

/** Plain name and one-line description declared in `definePlugin({ name, description })`. */
export function pluginInfo(o: GeneratePluginOutput): { name?: string; summary?: string } {
  const out: { name?: string; summary?: string } = {};
  const name = o.name ?? str(o.code, 'name');
  const summary = o.summary ?? str(o.code, 'description');
  if (name) out.name = name;
  if (summary) out.summary = summary;
  return out;
}

export const PERMISSIONS = ['read-events', 'write-events', 'network', 'docs'] as const;
export type PluginPermission = (typeof PERMISSIONS)[number];

/** Permissions the plugin declares (`permissions: [...]` in its manifest). */
export function declaredPermissions(o: GeneratePluginOutput): PluginPermission[] {
  const list = o.permissions ?? o.code.match(/\bpermissions\s*:\s*\[([^\]]*)\]/)?.[1] ?? '';
  const raw = Array.isArray(list)
    ? list
    : [...list.matchAll(/['"`]([a-z-]+)['"`]/g)].map((m) => m[1]);
  return PERMISSIONS.filter((p) => raw.includes(p));
}

/** Hooks the plugin implements, for the technical lens. */
export function pluginHooks(code: string): string[] {
  const hooks = ['onConnect', 'onAuth', 'onEvent', 'onReq', 'onUpload', 'onBlobServe'];
  return hooks.filter((h) => new RegExp(`\\b${h}\\s*[(:]`).test(code));
}

export interface TestCase {
  name: string;
  /** true passed, false failed, null unknown (the run did not report it by name). */
  ok: boolean | null;
  /** Failure details from the test output. */
  detail?: string;
}

/** Test names written in the test file (`test('…')` / `it('…')`). */
export function testNames(tests: string): string[] {
  return [...tests.matchAll(/\b(?:test|it)\s*\(\s*(['"`])((?:\\.|(?!\1).)*)\1/g)].map((m) =>
    (m[2] ?? '').replace(/\\(['"`\\])/g, '$1'),
  );
}

const RESULT_LINE = /^\s*(\(pass\)|\(fail\)|✓|✔|✗|✘|×)\s+(.+?)(?:\s+\[[\d.]+\s*m?s\])?\s*$/;

/**
 * Plain list of test cases with pass/fail. Uses the test runner output when
 * it names the tests (`(pass) suite > name`), else the names in the test file.
 */
export function testCases(o: GeneratePluginOutput): TestCase[] {
  const output = o.testResult?.output ?? '';
  const cases: TestCase[] = [];
  let pending: string[] = [];
  for (const line of output.split('\n')) {
    const m = line.match(RESULT_LINE);
    if (!m) {
      if (line.trim()) pending.push(line);
      continue;
    }
    const ok = m[1] === '(pass)' || m[1] === '✓' || m[1] === '✔';
    const full = m[2] ?? '';
    const name = full.split(' > ').pop() ?? full;
    const c: TestCase = { name, ok };
    if (!ok && pending.length) c.detail = pending.join('\n').trim();
    cases.push(c);
    pending = [];
  }
  if (cases.length) return cases;
  const names = testNames(o.tests);
  const allOk = o.tested && !!o.testResult?.ok;
  return names.map((name) => ({ name, ok: allOk ? true : null }));
}

/** Passed / failed counts (from the runner when it reports them). */
export function testCounts(o: GeneratePluginOutput): { passed: number; failed: number } {
  const cases = testCases(o);
  return {
    passed: o.testResult?.passed ?? cases.filter((c) => c.ok === true).length,
    failed: o.testResult?.failed ?? cases.filter((c) => c.ok === false).length,
  };
}

// ───────── "Written by the assistant" marker ─────────

/**
 * `plugins.status` rows do not say where a plugin came from (backend gap), so
 * the app remembers which plugins the assistant wrote, keyed by plugin id.
 * A row with `source: 'ai'` / `origin: 'ai'` is recognised too.
 */
export const AI_MARK_KEY = 'beamhop.plugins.ai';

interface KV {
  getItem(k: string): string | null;
  setItem(k: string, v: string): void;
}

const store = (): KV | null => {
  try {
    return typeof localStorage === 'undefined' ? null : localStorage;
  } catch {
    return null;
  }
};

export function aiMarked(kv: KV | null = store()): Set<string> {
  try {
    const v = JSON.parse(kv?.getItem(AI_MARK_KEY) ?? '[]') as unknown;
    return new Set(Array.isArray(v) ? v.filter((x): x is string => typeof x === 'string') : []);
  } catch {
    return new Set();
  }
}

export function markAi(id: string, on = true, kv: KV | null = store()): void {
  const ids = aiMarked(kv);
  if (on) ids.add(id);
  else ids.delete(id);
  try {
    kv?.setItem(AI_MARK_KEY, JSON.stringify([...ids].slice(-200)));
  } catch {
    // storage full or blocked: the badge is a convenience
  }
}

export function writtenByAssistant(
  id: string,
  row: { source?: unknown; origin?: unknown } | undefined,
  marked: Set<string>,
): boolean {
  return row?.source === 'ai' || row?.origin === 'ai' || marked.has(id);
}

// ───────── Discard with undo ─────────

/**
 * `plugins.uninstall` has no server-side undo, so Discard waits for the undo
 * window to pass before removing the plugin. `flush()` removes everything
 * still pending at once (e.g. when the screen closes).
 */
export class DeferredDiscard {
  private pending = new Map<string, ReturnType<typeof setTimeout>>();

  constructor(
    private remove: (id: string) => Promise<void> | void,
    private ms = 8000,
    private timers: {
      set: (fn: () => void, ms: number) => ReturnType<typeof setTimeout>;
      clear: (t: ReturnType<typeof setTimeout>) => void;
    } = { set: (fn, ms) => setTimeout(fn, ms), clear: (t) => clearTimeout(t) },
  ) {}

  has(id: string): boolean {
    return this.pending.has(id);
  }

  get ids(): string[] {
    return [...this.pending.keys()];
  }

  schedule(id: string): void {
    this.cancel(id);
    this.pending.set(
      id,
      this.timers.set(() => {
        this.pending.delete(id);
        void this.remove(id);
      }, this.ms),
    );
  }

  /** Undo: keep the plugin. Returns true when it was still pending. */
  cancel(id: string): boolean {
    const t = this.pending.get(id);
    if (t === undefined) return false;
    this.timers.clear(t);
    this.pending.delete(id);
    return true;
  }

  flush(): void {
    for (const id of this.ids) {
      this.cancel(id);
      void this.remove(id);
    }
  }
}
